        earlierCase.EventPlans[0].SchedulePlanner!.WalkoverMoves[esource.Id]=earlier.Changes;FixtureResets.ResetResult(earlierCase,esource);Check(earlierCase.EventPlans[0].SchedulePlanner!.WalkoverMoves.Count==0,"reset clears walkover undo timing metadata");
        var cutoff=Make(1,4);var cutEvent=cutoff.EventPlans[0];cutEvent.Sessions=[new(first,new(9,0),new(18,0),[1,2]),new(second,new(9,0),new(18,0),[1,2])];cutEvent.SchedulePlanner=new(){HasConfirmed=true};
        var cutMatches=cutoff.ProgramPlans[0].Matches;for(int i=0;i<2;i++){cutMatches[i].Start=(i==0?first:second).ToDateTime(new(9,0));cutMatches[i].End=cutMatches[i].Start!.Value.AddMinutes(30);cutMatches[i].DurationMinutes=30;cutMatches[i].Court=1;}
        var cutNodes=SchedulePlanner.Slots(cutoff,"E");cutEvent.SchedulePlanner.Minutes=cutNodes.GroupBy(n=>n.RoundKey).ToDictionary(g=>g.Key,g=>30);cutEvent.SchedulePlanner.Bookings=SchedulePlanner.Current(cutoff,"E",cutNodes);cutEvent.SchedulePlanner.Bookings.Add(new(cutNodes.Single(n=>n.Final).Id,second.ToDateTime(new(12,0)),2,30));
        cutMatches[0].Status=MatchStatus.Completed;cutMatches[0].WinnerId=cutMatches[0].EntryA;cutMatches[0].Games=[new(21,9)];
        foreach(var status in new[]{MatchStatus.Playing,MatchStatus.Review,MatchStatus.Completed,MatchStatus.Walkover}){cutMatches[1].Status=status;try{FixtureResets.ResetSchedule(cutoff,new(0,"E",second));Check(false,"protected range reset");}catch(RuleException){Check(cutEvent.SchedulePlanner.Bookings.Count==3&&cutMatches[1].Start.HasValue,"range reset is atomic for "+status);}}
        cutMatches[1].Status=MatchStatus.Scheduled;cutoff.Venue.Bindings.Add(new(){MatchId=cutMatches[1].Id});Check(FixtureResets.List(cutoff,"E",second).Blockers.Single().Reason.Contains("called"),"date preview names called blocker");cutoff.Venue.Bindings.Clear();
        var cutPreview=FixtureResets.List(cutoff,"E",second);Check(cutPreview.BookingCount==2&&cutPreview.Blockers.Length==0,"preview includes real and future-only reservations, excludes earlier result");
        FixtureResets.ResetSchedule(cutoff,new(0,"E",second));Check(cutMatches[0].Status==MatchStatus.Completed&&cutMatches[0].Start.HasValue&&cutMatches[0].Games.Count==1,"prior-day result and booking preserved");Check(cutMatches[1].Start is null&&cutoff.ProgramPlans[0].Matches.Count==2,"date reset clears booking without deleting draw");Check(cutEvent.SchedulePlanner.Bookings.Count==1&&cutEvent.Sessions.Count==2&&cutEvent.SchedulePlanner.Minutes.Count==2,"future reservations cleared; sessions and estimates retained");
        var cutRemaining=SchedulePlanner.Slots(cutoff,"E");var changedEstimate=SchedulePlanner.Configuration(cutoff,"E",cutRemaining);changedEstimate.Minutes[cutNodes[0].RoundKey]=40;try{SchedulePlanner.ValidateConfiguration(cutoff,"E",changedEstimate,cutRemaining);Check(false,"retained earlier round unlocked");}catch(RuleException){checks++;}
        Console.WriteLine($"PASS: {checks} whole-tournament planner rules checks");return checks;
    }
}
